#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

ENV_FILE=".env.local"
TOTAL_STAGES=7
cd "$(dirname "$0")/.."

cfg() { node -e 'const c=require("./lancamento.config.json");console.log(process.argv[1].split(".").reduce((o,k)=>o?.[k],c)??"")' "$1"; }
segredo() { node -e 'console.log(require("crypto").randomBytes(24).toString("hex"))'; }
manter() { local atual; atual=$(_existing "$1" || true); if [[ -n "$atual" ]]; then note "$1 já existe em $ENV_FILE: mantido."; else write_env "$1" "$2"; fi; }

SCHEMA=$(cfg banco.schema); FONTE=$(cfg inscritos.fonte); CONTA=$(cfg meta.contaAnuncios)
if [[ -z "$SCHEMA" || "$SCHEMA" == "exemplo" ]]; then
  printf '\n  lancamento.config.json ainda está com os valores de exemplo.\n  Faça o briefing primeiro (docs/BRIEFING.md) e rode de novo.\n\n'; exit 1
fi

banner "Acessos do painel · $(cfg nome)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Supabase: banco do painel (schema $SCHEMA)"
say "O painel guarda mídia, inscritos e vendas num schema só deste cliente."
open_url "https://supabase.com/dashboard/projects"
step "Abra o projeto que hospeda os painéis. Em Project Settings → Data API, copie a Project URL."
ask SUPABASE_URL "Cole a Project URL (https://xxxx.supabase.co):"
step "Em Project Settings → API Keys, copie a chave service_role (ou a secret key). Ela dá acesso total: nunca vai para o navegador nem para o repositório."
ask_secret SUPABASE_SERVICE_ROLE_KEY "Cole a chave service_role:"
write_env SUPABASE_URL "${SUPABASE_URL%/}"
write_env SUPABASE_SERVICE_ROLE_KEY "$SUPABASE_SERVICE_ROLE_KEY"
ARQ=$(node scripts/gerar-schema.mjs)
step "Abra o SQL Editor do projeto, cole o conteúdo de $ARQ e rode."
command -v pbcopy >/dev/null 2>&1 && pbcopy < "$ARQ" && note "(o SQL já está na área de transferência)"
pause "Rodou o SQL sem erro? Enter para continuar"
step "Em Project Settings → Data API → Exposed schemas, adicione \"$SCHEMA\" e salve. Sem isso a API responde que o schema não existe."
pause "Schema exposto? Enter para continuar"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Meta Ads: token de leitura"
say "O worker lê a conta $CONTA pela API de Marketing a cada 15 minutos."
open_url "https://business.facebook.com/settings/system-users"
step "No Gerenciador de Negócios dono da conta, crie (ou escolha) um Usuário do sistema."
step "Em Atribuir ativos, dê a ele a conta de anúncios $CONTA com permissão de ver desempenho."
step "Clique em Gerar token, escolha um app do negócio, marque só a permissão ads_read e, se houver a opção, validade sem expiração."
note "Os nomes dos menus mudam com frequência; se não achar, procure por 'Usuários do sistema' nas configurações do negócio."
ask_secret META_ACCESS_TOKEN "Cole o token:"
write_env META_ACCESS_TOKEN "$META_ACCESS_TOKEN"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Inscritos: fonte \"$FONTE\""
manter INGEST_SECRET "$(segredo)"
case "$FONTE" in
  sheets)
    PLANILHA=$(cfg inscritos.sheets.planilhaId)
    say "A planilha é lida por uma conta de serviço do Google. Você compartilha a planilha com o e-mail dela, como leitor."
    open_url "https://console.cloud.google.com/apis/library/sheets.googleapis.com"
    step "Escolha (ou crie) um projeto do Google Cloud e ative a Google Sheets API."
    open_url "https://console.cloud.google.com/iam-admin/serviceaccounts"
    step "Crie uma conta de serviço (não precisa de papel). Nela: Chaves → Adicionar chave → JSON. Um arquivo .json será baixado."
    ask CAMINHO_JSON "Arraste o arquivo .json para cá (ou cole o caminho):"
    CAMINHO_JSON="${CAMINHO_JSON//\\ / }"; CAMINHO_JSON="${CAMINHO_JSON%\'}"; CAMINHO_JSON="${CAMINHO_JSON#\'}"
    EMAIL_SA=$(node -e 'console.log(JSON.parse(require("fs").readFileSync(process.argv[1],"utf8")).client_email)' "$CAMINHO_JSON")
    write_env GOOGLE_SERVICE_ACCOUNT_JSON "$(base64 < "$CAMINHO_JSON" | tr -d '\n')"
    printf '\n  %sCompartilhe a planilha com este e-mail, como Leitor:%s\n  %s%s%s\n\n' "$BOLD" "$RESET" "$GREEN" "$EMAIL_SA" "$RESET"
    command -v pbcopy >/dev/null 2>&1 && printf '%s' "$EMAIL_SA" | pbcopy && note "(o e-mail já está na área de transferência)"
    open_url "https://docs.google.com/spreadsheets/d/$PLANILHA/edit"
    step "Na planilha: Compartilhar → cole o e-mail → Leitor → Enviar."
    pause "Compartilhou? Enter para continuar"
    warn "Apague o arquivo .json baixado: o conteúdo já está em $ENV_FILE."
    ;;
  supabase)
    say "Os inscritos estão na tabela $(cfg inscritos.supabase.tabela) do Supabase da página de captura."
    step "No projeto da página: Project Settings → Data API (URL) e API Keys (uma chave que leia a tabela)."
    ask LEADS_SUPABASE_URL "Cole a Project URL do Supabase da página:"
    ask_secret LEADS_SUPABASE_KEY "Cole a chave de leitura:"
    write_env LEADS_SUPABASE_URL "${LEADS_SUPABASE_URL%/}"
    write_env LEADS_SUPABASE_KEY "$LEADS_SUPABASE_KEY"
    note "Se a tabela negar leitura, rode lá: grant select on public.<tabela> to service_role;"
    ;;
  *)
    say "A página de captura avisa o painel a cada inscrição (webhook)."
    step "Depois do deploy, configure a página para enviar POST em <endereço do painel>/api/ingest/inscrito"
    step "com o cabeçalho Authorization: Bearer <INGEST_SECRET de $ENV_FILE>. O corpo está em docs/ACESSOS.md."
    pause "Anotado? Enter para continuar"
    ;;
esac

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Senha e segredos do painel"
say "O painel abre com uma senha única. Os segredos abaixo são gerados aqui."
ask_secret PAINEL_SENHA "Escolha a senha do painel:"
write_env PAINEL_SENHA "$PAINEL_SENHA"
manter PAINEL_SEGREDO "$(segredo)"
manter CRON_SECRET "$(segredo)"
warn "Não troque o PAINEL_SEGREDO depois que houver inscritos: ele embaralha e-mail e telefone, e trocar quebra o casamento com as vendas."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Telegram: relatório de hora em hora (opcional)"
if confirm "Quer receber o relatório no Telegram?"; then
  open_url "https://t.me/BotFather"
  step "No BotFather: /newbot, dê um nome e copie o token do bot."
  ask_secret TELEGRAM_BOT_TOKEN "Cole o token do bot:"
  step "Mande qualquer mensagem para o seu bot (ou adicione-o ao grupo que vai receber o relatório)."
  pause "Mandou? Enter para eu buscar o chat"
  CHATS=$(curl -fsS "https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/getUpdates" | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{const m=new Map();for(const u of JSON.parse(s).result||[]){const c=(u.message||u.channel_post||{}).chat;if(c)m.set(c.id,c.title||c.username||c.first_name||"")}for(const [i,n] of m)console.log(i+"  "+n)})' || true)
  say "Conversas encontradas:"; printf '%s\n' "${CHATS:-  (nenhuma: mande uma mensagem ao bot e rode de novo)}"
  ask TELEGRAM_CHAT_ID "Cole o número do chat que recebe o relatório:"
  write_env TELEGRAM_BOT_TOKEN "$TELEGRAM_BOT_TOKEN"
  write_env TELEGRAM_CHAT_ID "$TELEGRAM_CHAT_ID"
else
  note "Sem Telegram: o worker de relatório só devolve o texto."
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Teste das conexões"
say "Cada acesso é testado de verdade agora, só com leitura."
if node --env-file="$ENV_FILE" scripts/testar-acessos.mjs; then
  printf '\n  %s✓ todas as conexões responderam%s\n' "$GREEN" "$RESET"
else
  warn "Alguma conexão falhou (veja acima). Corrija e rode de novo: npm run acessos"
  SKIPPED+=("corrigir as conexões que falharam e rodar npm run testar-acessos")
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Vercel: publicar"
say "O deploy publica o painel e grava as variáveis de $ENV_FILE no projeto da Vercel."
if ! command -v vercel >/dev/null 2>&1; then
  warn "CLI da Vercel não instalada (npm i -g vercel)."; SKIPPED+=("instalar a CLI da Vercel e rodar: bash scripts/publicar.sh")
elif confirm "Publicar agora na Vercel? (as chaves vão para as variáveis de produção do projeto)"; then
  bash scripts/publicar.sh || SKIPPED+=("deploy falhou: rode bash scripts/publicar.sh")
  pause
else
  SKIPPED+=("publicar depois com: bash scripts/publicar.sh")
fi

finish
